Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma rc_A : forall regs m (s pixs comp : Z) (v : pixv) (ret : word),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs v -> (pixs + 64 <= s - 64)%Z -> p_cmap v = 0%Z -> p_d v = 32%Z ->
    (0 <= comp <= 2)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 comp ->
    exists regs',
      msteps SEGS (mkst regs (0x1ab98 : word) m rom) (mkst regs' (0x18f24 : word) (DIMc (FRM7 m s ret regs) s (p_w v) (p_h v)) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 1 = Z_to_bv 64 0x1acd0
      /\ getr regs' 10 = Z_to_bv 64 (p_w v) /\ getr regs' 11 = Z_to_bv 64 (p_h v) /\ getr regs' 12 = Z_to_bv 64 8
      /\ getr regs' 8 = Z_to_bv 64 comp /\ getr regs' 9 = Z_to_bv 64 pixs
