  (* [comment removed for export] *)
  Lemma rc_B : forall regs m (pixd pixs : Z),
    (1 <= pixd < 2 ^ 64)%Z -> getr regs 10 = Z_to_bv 64 pixd -> getr regs 9 = Z_to_bv 64 pixs ->
    exists regs',
      msteps SEGS (mkst regs (0x1acd0 : word) m rom) (mkst regs' (0x19764 : word) m rom)
      /\ getr regs' 1 = Z_to_bv 64 0x1ace0 /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 pixs /\ getr regs' 20 = Z_to_bv 64 pixd
      /\ regs_agree (fun x => In x [1; 11; 20]%list) regs regs'.
Proof.
