  (* [comment removed for export] *)
  Lemma rc_C : forall regs m (s pixs pixd comp : Z) (vs vd : pixv),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> (1 <= pixd)%Z -> PIXat m pixs vs -> PIXat m pixd vd -> (1 <= p_h vs)%Z -> (0 <= comp <= 2)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 64)) 4 = Some (w4 (Z_to_bv 64 (p_h vs))) ->
    rdn SEGS m (Z_to_bv 64 (s - 60)) 4 = Some (w4 (Z_to_bv 64 (p_w vs))) ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 9 = Z_to_bv 64 pixs -> getr regs 20 = Z_to_bv 64 pixd -> getr regs 8 = Z_to_bv 64 comp ->
    exists regs',
      msteps SEGS (mkst regs (0x1ace0 : word) m rom) (mkst regs' (0x1ad50 : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 11 = Z_to_bv 64 0 /\ getr regs' 8 = Z_to_bv 64 comp
      /\ getr regs' 9 = Z_to_bv 64 (p_data vs + comp) /\ getr regs' 18 = Z_to_bv 64 (4 * p_wpl vs) /\ getr regs' 19 = Z_to_bv 64 (4 * p_wpl vd)
      /\ getr regs' 12 = Z_to_bv 64 pixd /\ getr regs' 21 = Z_to_bv 64 pixd /\ getr regs' 20 = Z_to_bv 64 pixd /\ getr regs' 10 = Z_to_bv 64 (p_data vd)
      /\ getr regs' 13 = Z_to_bv 64 (p_h vs) /\ getr regs' 14 = Z_to_bv 64 (p_w vs)
      /\ regs_agree (fun x => In x [1; 8; 9; 10; 11; 12; 13; 14; 18; 19; 21]%list) regs regs'.
Proof.
