  Lemma rc_OH : forall regs m (w ps pd : Z),
    (1 <= w < 2 ^ 31)%Z -> getr regs 14 = Z_to_bv 64 w -> getr regs 9 = Z_to_bv 64 ps -> getr regs 10 = Z_to_bv 64 pd ->
    exists regs',
      msteps SEGS (mkst regs (0x1ad50 : word) m rom) (mkst regs' (0x1ad60 : word) m rom)
      /\ getr regs' 13 = Z_to_bv 64 0 /\ getr regs' 15 = Z_to_bv 64 ps /\ getr regs' 16 = Z_to_bv 64 pd
      /\ regs_agree (fun x => In x [13; 15; 16]%list) regs regs'.
