  (* [comment removed for export] *)
  Lemma rc_I : forall (last : bool) regs m (s j w p q : Z) (b : byte),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= j < w)%Z -> (w < 2 ^ 31)%Z -> (if last then j + 1 = w else j + 1 < w)%Z ->
    (0 <= p)%Z -> (p + 8 < 2 ^ 64)%Z -> (0 <= q)%Z -> (q + 8 < 2 ^ 64)%Z -> (xor3 q + 1 <= s - 64)%Z ->
    m (Z_to_bv 64 (xor3 p)) = Some b -> store_ok SEGS m (Z_to_bv 64 (xor3 q)) 1 = true ->
    rdn SEGS m (Z_to_bv 64 (s - 60)) 4 = Some (w4 (Z_to_bv 64 w)) ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 13 = Z_to_bv 64 j -> getr regs 15 = Z_to_bv 64 p -> getr regs 16 = Z_to_bv 64 q ->
    exists regs',
      msteps SEGS (mkst regs (0x1ad60 : word) m rom)
                  (mkst regs' (if last then (0x1ad3c : word) else (0x1ad60 : word)) (wbytes m (Z_to_bv 64 (xor3 q)) [Z_to_bv 8 (u (Z_to_bv 64 (u b)))]) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 64) /\ getr regs' 13 = Z_to_bv 64 (j + 1) /\ getr regs' 15 = Z_to_bv 64 (p + 4) /\ getr regs' 16 = Z_to_bv 64 (q + 1)
      /\ getr regs' 14 = Z_to_bv 64 w
      /\ regs_agree (fun x => In x [13; 14; 15; 16; 17]%list) regs regs'.
Proof.
