  (* [comment removed for export] *)
  Lemma rc_ON : forall (last : bool) regs m (s i h ls ld ss sd : Z),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= i < h)%Z -> (h < 2 ^ 31)%Z -> (if last then i + 1 = h else i + 1 < h)%Z ->
    (0 <= ls)%Z -> (0 <= ss)%Z -> (ls + ss < 2 ^ 64)%Z -> (0 <= ld)%Z -> (0 <= sd)%Z -> (ld + sd < 2 ^ 64)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 64)) 4 = Some (w4 (Z_to_bv 64 h)) ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 11 = Z_to_bv 64 i -> getr regs 9 = Z_to_bv 64 ls -> getr regs 18 = Z_to_bv 64 ss ->
    getr regs 10 = Z_to_bv 64 ld -> getr regs 19 = Z_to_bv 64 sd ->
    exists regs',
      msteps SEGS (mkst regs (0x1ad3c : word) m rom) (mkst regs' (if last then (0x1ad88 : word) else (0x1ad50 : word)) m rom)
      /\ getr regs' 11 = Z_to_bv 64 (i + 1) /\ getr regs' 9 = Z_to_bv 64 (ls + ss) /\ getr regs' 10 = Z_to_bv 64 (ld + sd) /\ getr regs' 13 = Z_to_bv 64 h
      /\ regs_agree (fun x => In x [9; 10; 11; 13]%list) regs regs'.
