  (* [comment removed for export] *)
  Lemma rc_E : forall regs r0 m (s pixd : Z) (ret : word),
    (64 <= s)%Z -> (s < 2 ^ 64)%Z -> ret_ok ret -> cellsZ m (frame7 s ret r0) ->
    getr regs 2 = Z_to_bv 64 (s - 64) -> getr regs 12 = Z_to_bv 64 pixd ->
    exists regs',
      msteps SEGS (mkst regs (0x1ad88 : word) m rom) (mkst regs' ret m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 10 = Z_to_bv 64 pixd
      /\ (forall x, In x [8; 9; 18; 19; 20; 21]%bv -> getr regs' x = getr r0 x)
